"""
Deploy the Voting.sol contract to Sepolia testnet.

Prerequisites:
  pip install web3

Usage:
  export ETH_RPC_URL=https://sepolia.infura.io/v3/YOUR_KEY
  export ETH_PRIVATE_KEY=0x...
  python scripts/deploy.py

Or set values in a .env file (see .env.example).
"""

import os
import json
import sys

from web3 import Web3

# ── ABI & Bytecode (compiled from Voting.sol via solc or Remix) ──
# To compile: solc --abi --bin Voting.sol -o build/
# Then paste the ABI JSON and hex bytecode below.

