# ── Bytecode (compiled from Voting.sol via solc 0.8.19) ──
CONTRACT_BYTECODE = ""


def load_config():
    """Load RPC URL and private key from environment."""
    rpc_url = os.environ.get("ETH_RPC_URL")
    private_key = os.environ.get("ETH_PRIVATE_KEY")

    if not rpc_url:
        print("ERROR: ETH_RPC_URL environment variable not set.")
        print("Example: export ETH_RPC_URL=https://sepolia.infura.io/v3/YOUR_KEY")
        sys.exit(1)
    if not private_key:
        print("ERROR: ETH_PRIVATE_KEY environment variable not set.")
        sys.exit(1)
    if private_key.startswith("0x"):
        private_key = private_key[2:]

    return rpc_url, private_key


def main():
    rpc_url, private_key = load_config()

    w3 = Web3(Web3.HTTPProvider(rpc_url))
    if not w3.is_connected():
        print(f"ERROR: Cannot connect to {rpc_url}")
        sys.exit(1)

    account = w3.eth.account.from_key(private_key)

    print(f"Deployer address: {account.address}")
    print(f"Balance: {w3.from_wei(w3.eth.get_balance(account.address), 'ether')} ETH")
    print(f"Chain ID: {w3.eth.chain_id}")

    Voting = w3.eth.contract(
        abi=CONTRACT_ABI,
        bytecode=CONTRACT_BYTECODE
    )

    nonce = w3.eth.get_transaction_count(account.address)

    tx = Voting.constructor().build_transaction({
        "from": account.address,
        "nonce": nonce,
        "chainId": 11155111,  # Sepolia
        "gas": 1000000,
        "maxFeePerGas": w3.to_wei(50, "gwei"),
        "maxPriorityFeePerGas": w3.to_wei(2, "gwei"),
    })

    signed_tx = account.sign_transaction(tx)

    tx_hash = w3.eth.send_raw_transaction(
        signed_tx.raw_transaction
    )

    print("Transaction sent!")
    print("TX Hash:", w3.to_hex(tx_hash))

    try:
        receipt = w3.eth.wait_for_transaction_receipt(
            tx_hash,
            timeout=300,
            poll_latency=5
        )

        contract_address = receipt.contractAddress

        print("\n✅ CONTRACT DEPLOYED")
        print("Contract Address:", contract_address)
        print(
            f"https://sepolia.etherscan.io/address/{contract_address}"
        )

    except Exception as e:
        print("Receipt wait failed:", str(e))
        print("Check transaction manually:")
        print(
            f"https://sepolia.etherscan.io/tx/{w3.to_hex(tx_hash)}"
        )


if __name__ == "__main__":
    main()
